update jewelry_staff set real_name=#{realName}, phone=#{phone}, status=#{status},
  joined_date=#{joinedDate}, update_by=#{updateBy}, update_time=sysdate(), remark=#{remark}
where staff_id=#{staffId}

update jewelry_product set product_name=#{productName},product_type=#{productType},
  category=#{category},specification=#{specification},image_url=#{imageUrl},image_urls=#{imageUrls},
  unit=#{unit},default_pack_fee=#{defaultPackFee},default_ship_fee=#{defaultShipFee},
  default_cert_fee=#{defaultCertFee},warning_qty=#{warningQty},status=#{status},
  update_by=#{updateBy},update_time=sysdate(),remark=#{remark}
where product_id=#{productId}

mapper.select:
select product_id from jewelry_product where product_id in
#{id}
order by product_id for update

mapper.update:
update jewelry_product
product_name=#{changes.productName}, product_type=#{changes.productType}, category=#{changes.category}, specification=#{changes.specification}, unit=#{changes.unit}, image_urls=#{changes.imageUrls},image_url=#{changes.imageUrls}, warning_qty=#{changes.warningQty}, status=#{changes.status}, default_pack_fee=#{changes.defaultPackFee}, default_ship_fee=#{changes.defaultShipFee}, default_cert_fee=#{changes.defaultCertFee}, update_by=#{userName},update_time=sysdate()
where product_id in #{id}

mapper.select:
select supplier_id supplierId,supplier_code supplierCode,supplier_name supplierName,
  status,remark
from jewelry_supplier where supplier_id=#{supplierId}

mapper.update:
update jewelry_supplier set supplier_name=#{supplierName},contact_name=#{contactName},
  contact_phone=#{contactPhone},address=#{address},settlement_type=#{settlementType},status=#{status},
  update_by=#{updateBy},update_time=sysdate(),remark=#{remark}
where supplier_id=#{supplierId}

update jewelry_influencer set external_influencer_id=#{externalInfluencerId},influencer_name=#{influencerName},platform=#{platform},
  platform_account=#{platformAccount},sales_channel=#{salesChannel},contact_phone=#{contactPhone},
  status=#{status},update_by=#{updateBy},update_time=sysdate(),remark=#{remark}
where influencer_id=#{influencerId}

update jewelry_influencer_product_price set price_status='PRICED',price_version=1,
  pending_source_document_id=null,price_source_document_id=#{sourceDocumentId},
  price_effective_time=sysdate(),update_by=#{userName},update_time=sysdate()
where influencer_id=#{influencerId} and product_id=#{productId}
  and price_status='PENDING' and pending_source_document_id=#{sourceDocumentId}

update jewelry_influencer_product_price set fixed_unit_price=#{fixedUnitPrice},
  price_version=price_version+1,price_effective_time=sysdate(),update_by=#{userName},update_time=sysdate()
where influencer_id=#{influencerId} and product_id=#{productId}
  and price_status='PRICED' and price_version=#{priceVersion}

update jewelry_supplier_return_mail_log
set status='FAILED',error_message=#{errorMessage}
where alert_date=#{alertDate} and status='SENDING'

mapper.select:
select t.transaction_id transactionId,t.document_id documentId,d.doc_no docNo,t.product_id productId, p.sku,p.product_name productName,t.transaction_type transactionType,t.on_hand_change onHandChange, t.reserved_change reservedChange,t.inspection_change inspectionChange,t.defect_change defectChange, t.before_on_hand beforeOnHand,t.after_on_hand afterOnHand,t.before_avg_cost beforeAvgCost, t.after_avg_cost afterAvgCost,t.operator_name operatorName,t.create_time createTime from jewelry_stock_transaction t join jewelry_document d on d.document_id=t.document_id join jewelry_product p on p.product_id=t.product_id
and t.product_id=#{productId}
order by t.transaction_id desc

select d.*,src.doc_type source_doc_type,src.doc_no source_doc_no, (select group_concat(distinct i.supplier_name_snapshot order by i.supplier_name_snapshot separator '、') from jewelry_document_item i where i.document_id=d.document_id and i.supplier_name_snapshot is not null and i.supplier_name_snapshot<>'') item_supplier_names from jewelry_document d left join jewelry_document src on src.document_id=d.source_document_id
and d.doc_no like concat('%',#{docNo},'%')
and d.doc_type in ('STOCK_ADJUST','COST_ADJUST')
and d.doc_type=#{docType}
and d.status in ('PENDING_FIRST','PENDING_SECOND') and d.status=#{status}
and d.status<>'DRAFT' and d.creator_user_id=#{creatorUserId}
order by d.document_id desc

select count(*) from jewelry_document
where doc_type='CUSTOMER_RETURN' and source_document_id=#{sourceDocumentId}
  and status in ('PENDING_FIRST','PENDING_SECOND','POSTED')

select count(*) from jewelry_document
where doc_type='SUPPLIER_RETURN' and source_document_id=#{sourceDocumentId}
  and status in ('PENDING_FIRST','PENDING_SECOND','POSTED')

mapper.update:
update jewelry_document_item set qty=#{qty},unit_price=#{unitPrice},unit_cost=#{unitCost},
  amount=#{amount},cost_amount=#{costAmount},profit_amount=#{profitAmount},profit_rate=#{profitRate}
where item_id=#{itemId}

update jewelry_stock set inspection_reserved_qty=inspection_reserved_qty+#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and inspection_qty-inspection_reserved_qty>=#{qty}

update jewelry_stock set inspection_reserved_qty=inspection_reserved_qty-#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and inspection_reserved_qty>=#{qty}

update jewelry_stock set defect_reserved_qty=defect_reserved_qty+#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and defect_qty-defect_reserved_qty>=#{qty}

update jewelry_stock set defect_reserved_qty=defect_reserved_qty-#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and defect_reserved_qty>=#{qty}
